(async()=>{const lists=[...document.querySelectorAll('[data-news-list]')];if(!lists.length)return;try{const r=await fetch('news-data.json',{cache:'no-cache'});if(!r.ok)return;const entries=await r.json();entries.sort((a,b)=>b.date.localeCompare(a.date));for(const list of lists){const full=list.dataset.newsList==='all',limit=full?entries.length:Number(list.dataset.newsList),fragment=document.createDocumentFragment();const selected=full?entries:entries.filter(item=>!item.archiveOnly).sort((a,b)=>(Number(b.priority)||0)-(Number(a.priority)||0)||b.date.localeCompare(a.date)).slice(0,limit).sort((a,b)=>b.date.localeCompare(a.date));for(const item of selected){const article=document.createElement('article');article.className='news-list-item';article.id='news-'+item.id;article.dataset.newsId=item.id;const time=document.createElement('time');time.dateTime=item.date;time.textContent=item.dateLabel||item.date;article.append(time);const content=document.createElement('div'),category=document.createElement('span'),heading=document.createElement('h3'),summary=document.createElement('p');content.className='news-copy';if(item.image&&item.imageAlt&&/^(assets\/|https:\/\/)/.test(item.image)){const image=document.createElement('img');image.className='news-photo';image.src=item.image;image.alt=item.imageAlt;image.width=112;image.height=84;image.loading='lazy';image.decoding='async';image.addEventListener('error',()=>image.remove(),{once:true});if(item.imagePresentation==='slide-presenter'){const frame=document.createElement('a');frame.className='news-slide-photo';frame.href=item.image;frame.setAttribute('aria-label','Open original panel photograph');frame.append(image);content.append(frame)}else{content.append(image)}}category.className='news-category';category.textContent=item.category;if(full&&!item.url){heading.textContent=item.title}else{const link=document.createElement('a');link.href=item.url||'news.html#news-'+item.id;link.textContent=item.title+(item.url?' ↗':' →');heading.append(link)}summary.textContent=item.summary;content.append(category,heading,summary);if(item.projectUrl){const project=document.createElement('a');project.href=item.projectUrl;project.className='news-project';project.textContent=(item.projectLabel||'Project website')+' ↗';content.append(project)}if(full&&item.relatedUrl){const related=document.createElement('a');related.href=item.relatedUrl;related.className='news-project';related.textContent=item.relatedLabel+' ↗';content.append(related)}if(full&&item.paperUrl){const paper=document.createElement('a');paper.href=item.paperUrl;paper.className='news-project';paper.textContent='CVPR workshop paper ↗';content.append(paper)}if(full&&item.details){const details=document.createElement('div');details.className='news-details';for(const text of item.details){const paragraph=document.createElement('p');paragraph.textContent=text;details.append(paragraph)}content.append(details)}article.append(content);fragment.append(article)}if(full){for(const article of fragment.children){const content=article.querySelector('.news-copy'),photo=content.querySelector('.news-slide-photo')||content.querySelector('.news-photo');if(photo){const media=document.createElement('div');media.className='news-media';media.append(photo);content.append(media)}}}list.replaceChildren(fragment)}}catch{ /* Pre-rendered entries remain available if fetching fails. */ }})();
